int simulate(int sx, int sy, int dir, int mx, int my, char *cmds, int ncmds) {
    int x = sx, y = sy;
    int d = dir;
    int ci = 0;
    while (1) {
        // Move forward until wall
        while (1) {
            int nx = x + dx[d];
            int ny = y + dy[d];
            if (nx < 0 || nx >= R || ny < 0 || ny >= C || grid[nx][ny] == '#') break;
            x = nx; y = ny;
            if (x == mx && y == my) return 1;
        }
        if (ci >= ncmds) return 0;
        char cmd = cmds[ci++];
        if (cmd == 'L') d = (d + 3) % 4;
        else d = (d + 1) % 4;
    }
}

int main() {
    int n;
    while (scanf("%d %d", &R, &C) == 2 && (R || C)) {
        int kx, ky, mx, my;
