                if (grid[i][j] == 'M') { mx = i; my = j; }
            }
        }
        char cmds[MAXCMD+1];
        scanf("%s", cmds);
        int ncmds = strlen(cmds);

        int go = simulate(kx, ky, 0, mx, my, cmds, ncmds);

        // Reverse commands with flipped directions
        char rcmds[MAXCMD+1];
        for (int i = 0; i < ncmds; i++) {
            char c = cmds[ncmds-1-i];
            rcmds[i] = (c == 'L') ? 'R' : 'L';
        }
        rcmds[ncmds] = '\0';

        int ret = 0;
