#include <stdio.h>
#include <string.h>

#define MAXH 105
#define MAXW 105
#define MAXN 10005

static int H, W;
static char g[MAXH][MAXW + 1];
static char cmd[MAXN];

int dr[4] = {-1, 0, 1, 0}; // N,E,S,W
int dc[4] = {0, 1, 0, -1};

int inside(int r, int c) {
    return r >= 0 && r < H && c >= 0 && c < W;
}

int iswall(int r, int c) {
    return !inside(r, c) || g[r][c] == '#';
}

void slide(int *r, int *c, int dir) {
    while (!iswall(*r + dr[dir], *c + dc[dir])) {
        *r += dr[dir];
        *c += dc[dir];
    }
}

int main(void) {
    while (scanf("%d %d", &H, &W) == 2) {
        if (H == 0 && W == 0) break;

        int sr = -1, sc = -1, mr = -1, mc = -1;
        for (int i = 0; i < H; i++) {
            scanf("%s", g[i]);
            for (int j = 0; j < W; j++) {
                if (g[i][j] == 'K') {
                    sr = i; sc = j;
                    g[i][j] = '.';
                } else if (g[i][j] == 'M') {
                    mr = i; mc = j;
                    g[i][j] = '.';
                }
            }
        }

        scanf("%s", cmd);
        int n = (int)strlen(cmd);

        int r = sr, c = sc, dir = 0; // initially facing north
        int ok1 = 1;

        for (int i = 0; i < n; i++) {
            slide(&r, &c, dir);
            if (cmd[i] == 'L' || cmd[i] == 'l')
                dir = (dir + 3) % 4;
            else
                dir = (dir + 1) % 4;
        }
        slide(&r, &c, dir);

        if (!(r == mr && c == mc)) ok1 = 0;

        int ok2 = 0;
        if (ok1) {
            for (int i = n - 1; i >= 0; i--) {
                if (cmd[i] == 'L' || cmd[i] == 'l')
                    dir = (dir + 1) % 4;   // flip L -> R
                else
                    dir = (dir + 3) % 4;   // flip R -> L
                slide(&r, &c, dir);
            }
            if (r == sr && c == sc) ok2 = 1;
        }

        if (ok1 && ok2) puts("He can accomplish his mission.");
        else if (ok1) puts("He can reach the target, but cannot return.");
        else puts("He cannot reach the target.");
    }
    return 0;
}

