struct State {
    int x, y, dir; // 0: up, 1: right, 2: down, 3: left
};

int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, 1, 0, -1};

int main() {
    int w, h;
    while (cin >> w >> h) {
        if (w == 0 && h == 0) break;
        vector<string> grid(h);
        int sx, sy, gx, gy;
        for (int i = 0; i < h; i++) {
            cin >> grid[i];
            for (int j = 0; j < w; j++) {
                if (grid[i][j] == 'K') { sx = i; sy = j; }
                if (grid[i][j] == 'M') { gx = i; gy = j; }
            }
        }
        string commands;
        cin >> commands;
        int n = commands.size();

        // Check if can reach master
        State cur = {sx, sy, 0}; // start facing up (north)
        bool reachMaster = false;
        for (int i = 0; i < n; i++) {
            // move until hitting a wall or leaving grid (but grid is bounded)
            while (true) {
                int nx = cur.x + dx[cur.dir];
                int ny = cur.y + dy[cur.dir];
                if (nx < 0 || nx >= h || ny < 0 || ny >= w || grid[nx][ny] == '#') {
                    break;
                }
                cur.x = nx;
                cur.y = ny;
                if (cur.x == gx && cur.y == gy) {
                    reachMaster = true;
                    break;
                }
            }
            if (reachMaster) break;
            // change direction
            if (commands[i] == 'L') {
                cur.dir = (cur.dir + 3) % 4; // turn left
            } else { // 'R'
                cur.dir = (cur.dir + 1) % 4; // turn right
            }
        }
        // After last command, still need to move until hit wall? 
        // Actually according to problem: after executing all commands, the doll continues moving until hitting a wall.
        while (!reachMaster) {
            int nx = cur.x + dx[cur.dir];
            int ny = cur.y + dy[cur.dir];
            if (nx < 0 || nx >= h || ny < 0 || ny >= w || grid[nx][ny] == '#') break;
            cur.x = nx;
            cur.y = ny;
            if (cur.x == gx && cur.y == gy) {
                reachMaster = true;
                break;
            }
        }

        // Now check return trip: reverse commands with flipped directions
        // Start from master's position (if reached) or from final position
        if (!reachMaster) {
            cout << "No" << endl;
            continue;
        }

        // For return, start from master's position
        State ret = {gx, gy, (cur.dir + 2) % 4}; // opposite direction
        bool backHome = false;
        // Reverse commands and flip L<->R
        string revCommands = commands;
        reverse(revCommands.begin(), revCommands.end());
        for (int i = 0; i < n; i++) {
            // move until hitting wall
            while (true) {
                int nx = ret.x + dx[ret.dir];
                int ny = ret.y + dy[ret.dir];
                if (nx < 0 || nx >= h || ny < 0 || ny >= w || grid[nx][ny] == '#') break;
                ret.x = nx;
                ret.y = ny;
                if (ret.x == sx && ret.y == sy) {
                    backHome = true;
                    break;
                }
            }
            if (backHome) break;
            // flip command
            if (revCommands[i] == 'L') {
                ret.dir = (ret.dir + 1) % 4; // flipped: L becomes R
            } else {
                ret.dir = (ret.dir + 3) % 4; // R becomes L
            }
        }
        // After last command, continue moving
        while (!backHome) {
            int nx = ret.x + dx[ret.dir];
            int ny = ret.y + dy[ret.dir];
            if (nx < 0 || nx >= h || ny < 0 || ny >= w || grid[nx][ny] == '#') break;
            ret.x = nx;
            ret.y = ny;
            if (ret.x == sx && ret.y == sy) {
                backHome = true;
                break;
            }
        }

        if (backHome) {
            cout << "Yes" << endl;
        } else {
            cout << "No" << endl;
        }
    }
    return 0;
}

