#include <bits/stdc++.h>
using namespace std;

struct State {
    int r, c, d;
    bool operator==(const State& other) const {
        return r == other.r && c == other.c && d == other.d;
    }
};

static const int dr[4] = {-1, 0, 1, 0}; // N,E,S,W
static const int dc[4] = {0, 1, 0, -1};

int dirFromChar(char ch) {
    if (ch == 'N') return 0;
    if (ch == 'E') return 1;
    if (ch == 'S') return 2;
    return 3; // W
}

char flipCmd(char ch) {
    return (ch == 'L') ? 'R' : 'L';
}

bool inBounds(int r, int c, int H, int W) {
    return 0 <= r && r < H && 0 <= c && c < W;
}

// Simulate one whole command sequence.
// The doll starts at (sr, sc) facing sd.
// For each command, it moves straight until the next cell would be a wall/outside,
// then turns according to the command.
// Returns true iff after processing all commands, position equals (tr, tc).
bool simulate(const vector<string>& g, int sr, int sc, int sd,
              const string& cmds, int tr, int tc,
              int &er, int &ec, int &ed) {
    int H = (int)g.size(), W = (int)g[0].size();
    int r = sr, c = sc, d = sd;

    // Detect infinite motion before hitting a wall.
    // State while moving straight is fully determined by (r,c,d) at cell boundaries.
    unordered_set<long long> seen;

    auto encode = [&](int r, int c, int d) -> long long {
        return ((long long)r << 32) ^ ((long long)c << 2) ^ d;
    };

    for (char cmd : cmds) {
        seen.clear();
        while (true) {
            int nr = r + dr[d], nc = c + dc[d];
            if (!inBounds(nr, nc, H, W) || g[nr][nc] == '#') break;

            long long key = encode(r, c, d);
            if (seen.count(key)) return false; // should not happen in normal grid, but safe
            seen.insert(key);

            r = nr;
            c = nc;
        }
        if (cmd == 'L') d = (d + 3) % 4;
        else d = (d + 1) % 4;
    }

    er = r; ec = c; ed = d;
    return (r == tr && c == tc);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    while (cin >> H >> W) {
        if (H == 0 && W == 0) break;

        vector<string> g(H);
        for (int i = 0; i < H; ++i) cin >> g[i];

        string cmds;
        cin >> cmds;

        int kr = -1, kc = -1, mr = -1, mc = -1, sd = 0;
        for (int i = 0; i < H; ++i) {
            for (int j = 0; j < W; ++j) {
                char ch = g[i][j];
                if (ch == 'K') {
                    kr = i; kc = j;
                } else if (ch == 'M') {
                    mr = i; mc = j;
                } else if (ch == 'N' || ch == 'E' || ch == 'S' || ch == 'W') {
                    kr = i; kc = j;
                    sd = dirFromChar(ch);
                }
            }
        }

        int r1, c1, d1;
        bool reachMaster = simulate(g, kr, kc, sd, cmds, mr, mc, r1, c1, d1);

        bool returnKitchen = false;
        if (reachMaster) {
            string rev = cmds;
            reverse(rev.begin(), rev.end());
            for (char &ch : rev) ch = flipCmd(ch);

            int r2, c2, d2;
            // To retrace, start from master's cell with opposite direction.
            returnKitchen = simulate(g, mr, mc, (d1 + 2) % 4, rev, kr, kc, r2, c2, d2);
        }

        if (reachMaster && returnKitchen) cout << "He can accomplish his mission.\n";
        else if (reachMaster) cout << "He can reach the target, but he cannot return.\n";
        else cout << "He cannot reach the target.\n";
    }

    return 0;
}

