            y = masterY;
            dir = 0; // reset direction to North for return

            // Build reverse commands with flipped directions
            StringBuilder revCommands = new StringBuilder();
            for (int i = commands.length() - 1; i >= 0; i--) {
                char c = commands.charAt(i);
                if (c == 'L') {
                    revCommands.append('R');
                } else { // 'R'
                    revCommands.append('L');
                }
            }

            boolean reachKitchen = false;
            for (int i = 0; i < revCommands.length(); i++) {
                char c = revCommands.charAt(i);
                if (c == 'L') {
                    dir = (dir + 3) % 4;
                } else {
                    dir = (dir + 1) % 4;
                }

                while (true) {
                    int nx = x + dx[dir];
                    int ny = y + dy[dir];
                    if (nx < 0 || nx >= h || ny < 0 || ny >= w || house[nx][ny] == '#') {
                        break;
                    }
                    x = nx;
                    y = ny;
                }

                if (x == startX && y == startY) {
                    reachKitchen = true;
                    break;
                }
            }

            if (reachKitchen) {
                System.out.println("Dataset " + dataset + ": Mission possible");
            } else {
                System.out.println("Dataset " + dataset + ": Unable to return");
            }
        }
    }
