import java.util.*;

public class Main {
    static char[][] grid;
    static int rows, cols;
    static int[] dr = {-1, 0, 1, 0}; // N, E, S, W
    static int[] dc = {0, 1, 0, -1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            rows = sc.nextInt(); cols = sc.nextInt();
            if (rows == 0 && cols == 0) break;
            grid = new char[rows][cols];
            int kr = -1, kc = -1, mr = -1, mc = -1;
            for (int i = 0; i < rows; i++) {
                String line = sc.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'K') { kr = i; kc = j; }
                    if (grid[i][j] == 'M') { mr = i; mc = j; }
                }
            }
            String commands = sc.next();
            // Try all 4 initial directions
            boolean canReach = false, canReturn = false;
            for (int initDir = 0; initDir < 4 && !canReach; initDir++) {
                int[] result = simulate(kr, kc, initDir, commands, mr, mc);
                if (result != null) {
                    canReach = true;
                    // Return: start at M, face opposite of arrival direction, reverse+flip commands
                    int arrDir = result[0];
                    int retDir = (arrDir + 2) % 4;
                    StringBuilder rev = new StringBuilder();
                    for (int i = commands.length() - 1; i >= result[1] - 1; i--) {
                        // result[1] is number of commands used
                        if (i < commands.length()) {
                            char c = commands.charAt(i);
                            rev.append(c == 'L' ? 'R' : 'L');
                        }
                    }
                    // Actually reverse and flip all commands up to result[1]
                    String usedCmds = commands.substring(0, result[1]);
                    StringBuilder retCmds = new StringBuilder();
                    for (int i = usedCmds.length() - 1; i >= 0; i--) {
                        retCmds.append(usedCmds.charAt(i) == 'L' ? 'R' : 'L');
                    }
                    int[] ret = simulate(mr, mc, retDir, retCmds.toString(), kr, kc);
                    if (ret != null) canReturn = true;
                }
            }
            if (canReach && canReturn) System.out.println("OK");
            else if (canReach) System.out.println("NG"); // reached but can't return
            else System.out.println("NG");
        }
    }

    static int[] simulate(int sr, int sc2, int dir, String cmds, int tr, int tc) {
        int r = sr, c = sc2, cmdIdx = 0;
        for (int steps = 0; steps < 10000; steps++) {
            int nr = r + dr[dir], nc = c + dc[dir];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr][nc] == '#') {
                if (cmdIdx >= cmds.length()) return null;
                char cmd = cmds.charAt(cmdIdx++);
                if (cmd == 'L') dir = (dir + 3) % 4;
                else dir = (dir + 1) % 4;
            } else {
                r = nr; c = nc;
                if (r == tr && c == tc) return new int[]{dir, cmdIdx};
            }
        }
        return null;
    }
}

