public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int H, W;
    static char[][] grid;

    // 0: up, 1: right, 2: down, 3: left
    static final int[] dr = {-1, 0, 1, 0};
    static final int[] dc = {0, 1, 0, -1};

    static boolean in(int r, int c) {
        return 0 <= r && r < H && 0 <= c && c < W;
    }

    static boolean wall(int r, int c) {
        return !in(r, c) || grid[r][c] == '#';
    }

    static class State {
        int r, c, dir;
        State(int r, int c, int dir) {
            this.r = r;
            this.c = c;
            this.dir = dir;
        }
    }

    static State simulate(int sr, int sc, int sdir, char[] cmds) {
        int r = sr, c = sc, dir = sdir;

        for (char cmd : cmds) {
            while (!wall(r + dr[dir], c + dc[dir])) {
                r += dr[dir];
                c += dc[dir];
            }
            if (cmd == 'L') dir = (dir + 3) % 4;
            else dir = (dir + 1) % 4;
        }
        while (!wall(r + dr[dir], c + dc[dir])) {
            r += dr[dir];
            c += dc[dir];
        }
        return new State(r, c, dir);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            String first = fs.next();
            if (first == null) break;
            H = Integer.parseInt(first);
            W = fs.nextInt();
            if (H == 0 && W == 0) break;

            grid = new char[H][];
            int kr = -1, kc = -1, mr = -1, mc = -1;

            for (int i = 0; i < H; i++) {
                grid[i] = fs.next().toCharArray();
                for (int j = 0; j < W; j++) {
                    if (grid[i][j] == 'K') {
                        kr = i; kc = j;
                        grid[i][j] = '.';
                    } else if (grid[i][j] == 'M') {
                        mr = i; mc = j;
                        grid[i][j] = '.';
                    }
                }
            }

            String s = fs.next();
            char[] cmds = s.toCharArray();

            boolean ok = false;

            for (int dir = 0; dir < 4 && !ok; dir++) {
                State go = simulate(kr, kc, dir, cmds);
                if (go.r == mr && go.c == mc) {
                    char[] rev = new char[cmds.length];
                    for (int i = 0; i < cmds.length; i++) {
                        char ch = cmds[cmds.length - 1 - i];
                        rev[i] = (ch == 'L') ? 'R' : 'L';
                    }
                    State back = simulate(mr, mc, (go.dir + 2) % 4, rev);
                    if (back.r == kr && back.c == kc) {
                        ok = true;
                    }
                }
            }

            out.append(ok ? "Yes" : "No").append('\n');
        }

        System.out.print(out.toString());
    }
}

import sys

def solve():
    data = sys.stdin.read().splitlines()
    out = []
    i = 0

    # Directions: 0=up, 1=right, 2=down, 3=left
    dr = [-1, 0, 1, 0]
    dc = [0, 1, 0, -1]

    while i < len(data):
        if not data[i].strip():
            i += 1
            continue

        w_h = data[i].split()
        i += 1
        if len(w_h) < 2:
            continue
        W, H = map(int, w_h)
        if W == 0 and H == 0:
            break

        grid = []
        for _ in range(H):
            grid.append(list(data[i].rstrip('\n')))
            i += 1

        n = int(data[i].strip())
        i += 1
        cmds = []
        while len(cmds) < n:
            parts = data[i].split()
            cmds.extend(parts)
            i += 1
        cmds = cmds[:n]

        kitchen = master = None
        for r in range(H):
            for c in range(W):
                if grid[r][c] == 'K':
                    kitchen = (r, c)
                elif grid[r][c] == 'M':
                    master = (r, c)

        def inside(r, c):
            return 0 <= r < H and 0 <= c < W

        def is_wall(r, c):
            return not inside(r, c) or grid[r][c] == '#'

        def simulate(start_pos, start_dir, command_list):
            r, c = start_pos
            d = start_dir
            for cmd in command_list:
                nr, nc = r + dr[d], c + dc[d]
                while not is_wall(nr, nc):
                    r, c = nr, nc
                    nr += dr[d]
                    nc += dc[d]

                if cmd[0].lower() == 'l':
                    d = (d + 3) % 4
                else:
                    d = (d + 1) % 4
            return (r, c), d

        reached = False
        returnable = False

        # Try all possible initial facing directions.
        for init_dir in range(4):
            pos1, dir1 = simulate(kitchen, init_dir, cmds)
            if pos1 == master:
                reached = True

                rev_cmds = [('R' if c[0].lower() == 'l' else 'L') for c in reversed(cmds)]
                pos2, dir2 = simulate(master, dir1, rev_cmds)
                if pos2 == kitchen:
                    returnable = True
                    break

        if not reached:
            out.append("No")
        elif returnable:
            out.append("Yes")
        else:
            out.append("No")

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
